insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en,warning_fa,warning_en) values
('guidance.experience_mode','حالت Basic و Advanced','در حالت Basic کنترل‌های ضروری نمایش داده می‌شوند تا پنل ساده بماند. Advanced برای مدیران حرفه‌ای است و گزینه‌های بیشتر را نشان می‌دهد. این تنظیم برای هر مدیر و هر Tenant جدا ذخیره می‌شود.','Basic and Advanced modes','Basic mode keeps everyday controls simple. Advanced mode reveals more professional controls. The preference is stored separately for each user and tenant.',null,null),
('guidance.tours','تورهای آموزشی','تورهای کوتاه فقط بخش‌های مهم را معرفی می‌کنند، قابل رد کردن و اجرای مجدد هستند و پیشرفت هر مدیر ذخیره می‌شود. با تغییر نسخه یک قابلیت می‌توان تور جدید همان بخش را دوباره نمایش داد.','Guided tours','Short tours introduce only important areas, can be skipped or replayed, and store progress per administrator. A new feature version can trigger an updated tour.',null,null),
('guidance.help_center','مرکز راهنما','آموزش‌های فارسی و انگلیسی را بر اساس موضوع یا عبارت جستجو کنید. محتوای راهنما با نقش و سطح دسترسی کاربر هماهنگ می‌شود.','Help Center','Search bilingual guidance by topic or phrase. Guidance is filtered to match the user role and access level.',null,null),
('theme.switch','تغییر قالب سایت','تغییر Theme فقط لایه نمایش را عوض می‌کند و محتوای سایت حذف نمی‌شود. ابتدا تغییر را به‌صورت Draft ذخیره و Preview کنید.','Switch site theme','Changing a theme affects presentation, not site content. Save changes as a draft and preview them before publishing.',null,null),
('theme.publish','انتشار Theme','Publish تنظیمات Draft ظاهر را برای بازدیدکنندگان فعال می‌کند. نسخه قبلی برای Restore نگهداری می‌شود.','Publish theme','Publishing makes the draft appearance public. The previous version is kept for restoration.','قبل از انتشار، Preview و Tenant فعال را بررسی کنید.','Verify the preview and active tenant before publishing.'),
('theme.registry','مدیریت Theme Registry','Theme Registry برای اضافه‌کردن نسخه‌های جدید، Deprecated و Archive کردن قالب‌هاست. این بخش فقط برای تیم سطح پلتفرم است.','Manage Theme Registry','Theme Registry manages new theme versions, deprecation and archival. It is a platform-level capability.','Theme فعال روی مشتری را قبل از Archive حذف نکنید؛ ابتدا جایگزین تعیین شود.','Do not archive a theme that is still active for a tenant; assign a replacement first.')
